#include "stdlib/math/base/special/tanhf.h"
#include <math.h>

// log(2**127)
static const float MAXLOG = 8.8029691931113054295988e+01f;

/* Begin auto-generated functions. The following functions are auto-generated. Do not edit directly. */

// BEGIN: rational_pq

/**
* Evaluates a rational function (i.e., the ratio of two polynomials described by the coefficients stored in \\(P\\) and \\(Q\\)).
*
* ## Notes
*
* -   Coefficients should be sorted in ascending degree.
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the rational function
* @return     evaluated rational function
*/
static float rational_pq( const float x ) {
	float ax;
	float ix;
	float s1;
	float s2;
	if ( x == 0.0f ) {
		return -0.3333333333333332f;
	}
	if ( x < 0.0f ) {
		ax = -x;
	} else {
		ax = x;
	}
	if ( ax <= 1.0f ) {
		s1 = -1614.6876844170845f + (x * (-99.28772310019185f + (x * (-0.9643991794250523f + (x * 0.0f)))));
		s2 = 4844.063053251255f + (x * (2235.4883906010045f + (x * (112.81167849163293f + (x * 1.0f)))));
	} else {
		ix = 1.0f / x;
		s1 = 0.0f + (ix * (-0.9643991794250523f + (ix * (-99.28772310019185f + (ix * -1614.6876844170845f)))));
		s2 = 1.0f + (ix * (112.81167849163293f + (ix * (2235.4883906010045f + (ix * 4844.063053251255f)))));
	}
	return s1 / s2;
}

// END: rational_pq

/* End auto-generated functions. */

/**
* Computes the hyperbolic tangent of a single-precision floating-point number.
*
* ## Method
*
* For \\( |x| < 0.625 \\), we use a rational function of the form (Cody and Waite)
*
* ```tex
* x + x^3 \frac{\mathrm{P}(x)}{\mathrm{Q}(x)}
* ```
*
* Otherwise,
*
* ```tex
* \begin{align*}
* \operatorname{tanhf}(x) &= \frac{\operatorname{sinhf}(x)}{\operatorname{coshf(x)}} \\
* &= 1 - \frac{2}{e^{2x} + 1}
* \end{align*}
* ```
*
* ## Notes
*
* -   Relative error:
*
*     | arithmetic | domain | # trials | peak    | rms     |
*     |:----------:|:------:|:--------:|:-------:|:-------:|
*     | IEEE       | -2,2   | 100000   | 1.7e-7  | 4.0e-8  |
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_tanhf( 0.0f );
* // returns 0.0f
*/
float stdlib_base_tanhf( const float x ) {
	float s;
	float z;
	z = fabsf( x );
	if ( z > 0.5f * MAXLOG ) {
		return ( x < 0.0f ) ? -1.0f : 1.0f;
	}
	if ( z >= 0.625f ) {
		s = expf( 2.0f * z );
		z = 1.0f - ( 2.0f / ( s + 1.0f ) );
		if ( x < 0.0f ) {
			z = -z;
		}
	} else {
		if ( x == 0.0f ) {
			return x; // Handle `+-0`
		}
		s = x * x;
		z = x + ( x * s * rational_pq( s ) );
	}
	return z;
}
